// Route based on trigger type
const isScheduled = $input.first().json.hasOwnProperty('__scheduled') || !$input.first().json.type;

if (isScheduled) {
  return {
    triggerType: 'scheduled_digest',
    timestamp: new Date().toISOString()
  };
}

// Parse Discord webhook payload
const payload = $input.first().json;

return {
  triggerType: 'discord_event',
  eventType: payload.type || payload.event_type,
  guildId: payload.guild_id,
  channelId: payload.channel_id,
  userId: payload.user_id || payload.author?.id,
  userName: payload.user_name || payload.author?.username,
  messageContent: payload.content || payload.message?.content,
  messageId: payload.id || payload.message?.id,
  timestamp: payload.timestamp || new Date().toISOString(),
  rawPayload: payload
};

// Format security digest for Discord
const items = $input.all().map(item => item.json);

if (items.length === 0) {
  return {
    skip: true,
    reason: 'No critical or high severity items in the last 6 hours'
  };
}

// Group by severity
const critical = items.filter(i => i.severity === 'critical');
const high = items.filter(i => i.severity === 'high');

// Build Discord embed
const embed = {
  title: '🔒 Security Digest - Critical Updates',
  description: `${items.length} critical and high severity items in the last 6 hours`,
  color: critical.length > 0 ? 15158332 : 15105570, // Red for critical, orange for high
  fields: [],
  timestamp: new Date().toISOString(),
  footer: {
    text: 'Bug Bounty KSP Security Aggregator'
  }
};

if (critical.length > 0) {
  embed.fields.push({
    name: '🔴 Critical Issues',
    value: critical.slice(0, 5).map(item => 
      `**${item.title.substring(0, 100)}**\n${item.source} | [Link](${item.url})`
    ).join('\n\n'),
    inline: false
  });
}

if (high.length > 0) {
  embed.fields.push({
    name: '🟠 High Priority',
    value: high.slice(0, 5).map(item => 
      `**${item.title.substring(0, 100)}**\n${item.source} | [Link](${item.url})`
    ).join('\n\n'),
    inline: false
  });
}

return {
  embeds: [embed],
  content: `@here New security digest available with ${critical.length} critical and ${high.length} high priority items.`,
  skip: false
};

// Handle Discord commands
const message = ($json.messageContent || '').trim();
const userId = $json.userId;
const userName = $json.userName;

if (!message.startsWith('!')) {
  return {
    skip: true,
    reason: 'Not a command'
  };
}

// Parse command
const parts = message.substring(1).split(' ');
const command = parts[0].toLowerCase();
const args = parts.slice(1);

const validCommands = {
  'help': 'Show available commands',
  'search': 'Search for vulnerabilities: !search <keyword>',
  'subscribe': 'Subscribe to notifications: !subscribe <category>',
  'unsubscribe': 'Unsubscribe from notifications: !unsubscribe <category>',
  'stats': 'Show your bug bounty stats',
  'leaderboard': 'Show community leaderboard',
  'report': 'Submit a vulnerability report',
  'learning': 'Get your learning path progress'
};

return {
  ...($json),
  command: command,
  args: args,
  validCommand: Object.keys(validCommands).includes(command),
  commandList: validCommands,
  skip: false
};

// Execute command logic
const command = $json.command;
const args = $json.args;
const userId = $json.userId;
const userName = $json.userName;

let response = {
  embeds: [],
  content: ''
};

switch (command) {
  case 'help':
    response.embeds.push({
      title: '🤖 Bot Commands',
      description: 'Available commands for Bug Bounty KSP Bot',
      color: 3447003,
      fields: Object.entries($json.commandList).map(([cmd, desc]) => ({
        name: `!${cmd}`,
        value: desc,
        inline: false
      }))
    });
    break;

  case 'search':
    if (args.length === 0) {
      response.content = '❌ Please provide a search keyword. Usage: `!search <keyword>`';
    } else {
      response.searchKeyword = args.join(' ');
      response.needsSearch = true;
    }
    break;

  case 'subscribe':
    if (args.length === 0) {
      response.content = '❌ Please specify a category. Usage: `!subscribe <vulnerability|bug-bounty|exploit|patch>`';
    } else {
      response.subscribeCategory = args[0];
      response.needsSubscribe = true;
    }
    break;

  case 'unsubscribe':
    if (args.length === 0) {
      response.content = '❌ Please specify a category. Usage: `!unsubscribe <category>`';
    } else {
      response.unsubscribeCategory = args[0];
      response.needsUnsubscribe = true;
    }
    break;

  case 'stats':
    response.needsStats = true;
    break;

  case 'leaderboard':
    response.needsLeaderboard = true;
    break;

  case 'report':
    response.embeds.push({
      title: '📝 Submit Vulnerability Report',
      description: 'To submit a vulnerability report, please use our web form or API endpoint.',
      color: 15105570,
      fields: [
        {
          name: 'Web Form',
          value: '[Submit Report](https://bugbounty.com/submit)',
          inline: true
        },
        {
          name: 'API',
          value: 'POST /api/vulnerabilities',
          inline: true
        }
      ]
    });
    break;

  case 'learning':
    response.needsLearningPath = true;
    break;

  default:
    response.content = '❌ Unknown command. Type `!help` for available commands.';
}

return {
  ...($json),
  response: response
};

// Format search results or command response
const commandData = $input.first().json;
const searchResults = $input.all().slice(1).map(item => item.json);

let finalResponse = commandData.response;

// Handle search results
if (commandData.response.needsSearch && searchResults.length > 0) {
  const resultsText = searchResults.slice(0, 5).map((item, idx) => 
    `${idx + 1}. **${item.title}**\n` +
    `   ${item.severity ? '`' + item.severity + '`' : ''} ${item.category ? '`' + item.category + '`' : ''}\n` +
    `   ${item.description.substring(0, 100)}...\n` +
    `   [Link](${item.url})`
  ).join('\n\n');

  finalResponse.embeds.push({
    title: `🔍 Search Results for "${commandData.response.searchKeyword}"`,
    description: resultsText || 'No results found',
    color: 3447003,
    footer: {
      text: `Found ${searchResults.length} results`
    }
  });
  finalResponse.content = `Found ${searchResults.length} results for "${commandData.response.searchKeyword}"`;
}

// Handle stats (mock data for now)
if (commandData.response.needsStats) {
  finalResponse.embeds.push({
    title: `📊 Stats for ${commandData.userName}`,
    color: 3066993,
    fields: [
      { name: 'Vulnerabilities Found', value: '12', inline: true },
      { name: 'Bounties Earned', value: '$2,500', inline: true },
      { name: 'Reputation Score', value: '847', inline: true },
      { name: 'Learning Progress', value: '65%', inline: true },
      { name: 'Community Rank', value: '#42', inline: true },
      { name: 'Active Days', value: '87', inline: true }
    ]
  });
  finalResponse.content = `Here are your stats, ${commandData.userName}! 🎯`;
}

// Handle leaderboard (mock data)
if (commandData.response.needsLeaderboard) {
  finalResponse.embeds.push({
    title: '🏆 Community Leaderboard',
    description: 'Top bug bounty hunters this month',
    color: 15844367,
    fields: [
      { name: '🥇 1st Place', value: 'HackerOne ($15,000 | 42 vulns)', inline: false },
      { name: '🥈 2nd Place', value: 'SecurityPro ($12,500 | 38 vulns)', inline: false },
      { name: '🥉 3rd Place', value: 'BugHunter ($10,000 | 35 vulns)', inline: false },
      { name: '4th Place', value: 'WhiteHat ($8,500 | 30 vulns)', inline: false },
      { name: '5th Place', value: 'CyberNinja ($7,000 | 28 vulns)', inline: false }
    ]
  });
  finalResponse.content = 'Here\'s the current leaderboard! 🏆';
}

// Handle learning path
if (commandData.response.needsLearningPath) {
  finalResponse.embeds.push({
    title: '📚 Your Learning Path Progress',
    color: 9807270,
    fields: [
      { name: 'Current Milestone', value: 'Web Application Security Fundamentals', inline: false },
      { name: 'Progress', value: '4/7 milestones completed (57%)', inline: false },
      { name: 'Next Up', value: 'Advanced SQL Injection Techniques', inline: false },
      { name: 'Estimated Time Remaining', value: '8 weeks', inline: true },
      { name: 'Resources Completed', value: '24/42', inline: true }
    ]
  });
  finalResponse.content = `Great progress, ${commandData.userName}! Keep it up! 🚀`;
}

// Handle subscribe/unsubscribe
if (commandData.response.needsSubscribe) {
  finalResponse.content = `✅ Successfully subscribed to **${commandData.response.subscribeCategory}** notifications!`;
}

if (commandData.response.needsUnsubscribe) {
  finalResponse.content = `✅ Successfully unsubscribed from **${commandData.response.unsubscribeCategory}** notifications!`;
}

return {
  ...commandData,
  finalResponse: finalResponse
};

